  WHERE existing.id IS NULL OR existing.pos IS NOT v.column2 OR existing.meaning IS NOT v.column3 OR existing.level IS NOT v.column4 OR existing.source IS NOT 'JLPT-tanos'
ON CONFLICT(lang, word) DO UPDATE SET pos=excluded.pos, meaning=excluded.meaning, level=excluded.level, source=excluded.source
WHERE words.pos IS NOT excluded.pos OR words.meaning IS NOT excluded.meaning OR words.level IS NOT excluded.level OR words.source IS NOT excluded.source;

