  ) AS v JOIN words w ON w.lang = 'ko' AND w.word = v.column1
  LEFT JOIN word_meanings existing ON existing.word_id = w.id AND existing.locale = 'en'
  WHERE existing.meaning IS NOT v.column2
ON CONFLICT(word_id, locale) DO UPDATE SET meaning=excluded.meaning WHERE word_meanings.meaning IS NOT excluded.meaning;

